    int acc = INIT_FOR(OP);
    RUN_LOOP(OP, acc, REPEAT);
    printf("helper.call=%d helper.acc=%d\n", r, acc);
    return r + acc;
}

int helper_ptr(int a, int b) {
    int (*fp)(int,int) = OP_FN(OP);
    int r = fp(a, b);
    printf("helper.ptr=%d\n", r);
    return r;
}

int use_generated(int n) {
    int r = (ACCUM_FN(OP))(n);
    printf("gen.acc=%d\n", r);
    return r;
}
